from pathlib import Path
import argparse,json,hashlib
p=argparse.ArgumentParser();p.add_argument('--official',type=Path,required=True);p.add_argument('--rust',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();go=json.loads(a.official.read_text());rs=json.loads(a.rust.read_text());assert go['status']==rs['status']=='PASS_SCOPED';assert go['cases_sha256']==rs['cases_sha256'];assert go['component_source_sha256']==rs['component_source_sha256'];assert not go['cleanup_errors']and not rs['cleanup_errors'];assert len(go['rows'])==len(rs['rows'])==12
columns=['id','join_permission_sources','allowed','track_source','denied_echo_source','reason','denial_message','owner_barrier','api_matches','api_repeated_matches','api_permission_sources','api_raw_sources','api_allowed','api_after','updates'];equal=all({k:g[k]for k in columns}=={k:r[k]for k in columns}for g,r in zip(go['rows'],rs['rows']));out={'status':'PASS_SCOPED'if equal else'FAIL','numeric_source_fields_exact':equal,'separate_denial_diagnostic_exact':[g['denial_message']==r['denial_message']for g,r in zip(go['rows'],rs['rows'])],'selected_denial_message_exact_required':True,'official_sha256':hashlib.sha256(a.official.read_bytes()).hexdigest(),'rust_sha256':hashlib.sha256(a.rust.read_bytes()).hexdigest()};a.output.write_text(json.dumps(out,indent=2)+'\n');assert equal
